-- BMLT NHPC: Medical Microbiology bulk batch 2
-- 20 MCQ practice + 20 separate mock questions; bilingual explanations.
-- Independent educational practice questions; not official past questions.
begin;
on conflict (content_id) do update set
 faculty=excluded.faculty, subject=excluded.subject, content_type=excluded.content_type,
 access_tier=excluded.access_tier, display_order=excluded.display_order,
 content_data=excluded.content_data, is_published=excluded.is_published, updated_at=now();
commit;
select faculty,subject,content_type,count(*) total
from public.learning_content
where faculty='BMLT' and subject='Medical Microbiology'
group by faculty,subject,content_type;
