values
('bmlt-micro-mcq-001','BMLT','Medical Microbiology','mcq','free',1,'{"question":"Gram-positive cocci in clusters that are catalase-positive and coagulase-positive are most consistent with:","translation":"Catalase र coagulase positive cluster मा देखिने Gram-positive cocci कुन हो?","options":["Staphylococcus aureus","Streptococcus pyogenes","Enterococcus faecalis","Neisseria gonorrhoeae"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"S. aureus is a catalase-positive staphylococcus and is typically coagulase-positive.","topic":"S. aureus catalase र coagulase दुवै positive हुन्छ; cluster मा देखिन्छ।"}'::jsonb,true),
('bmlt-micro-mcq-002','BMLT','Medical Microbiology','mcq','free',2,'{"question":"Which medium is selective for Mycobacterium tuberculosis culture?","translation":"M. tuberculosis culture का लागि कुन selective medium प्रयोग हुन्छ?","options":["Lowenstein–Jensen medium","MacConkey agar","Sabouraud agar","Thayer–Martin agar"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"Lowenstein–Jensen medium supports mycobacterial culture and is selective.","topic":"Lowenstein–Jensen medium mycobacteria culture का लागि प्रयोग हुन्छ।"}'::jsonb,true),
('bmlt-micro-mcq-003','BMLT','Medical Microbiology','mcq','free',3,'{"question":"A sputum smear for acid-fast bacilli is commonly stained by:","translation":"Sputum मा acid-fast bacilli हेर्न सामान्यतया कुन stain गरिन्छ?","options":["Ziehl–Neelsen stain","India ink","Albert stain","Lactophenol cotton blue"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"Ziehl–Neelsen staining demonstrates acid-fast bacilli such as M. tuberculosis.","topic":"Ziehl–Neelsen stain ले M. tuberculosis जस्ता acid-fast bacilli देखाउँछ।"}'::jsonb,true),
('bmlt-micro-mcq-004','BMLT','Medical Microbiology','mcq','free',4,'{"question":"The organism responsible for diphtheria produces disease mainly through:","translation":"Diphtheria को रोग उत्पन्न गर्ने मुख्य कारण के हो?","options":["Exotoxin","Endotoxin only","Capsule only","Flagellar invasion"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"Corynebacterium diphtheriae causes major pathology through diphtheria toxin.","topic":"C. diphtheriae को diphtheria toxin ले मुख्य रोगजन्य असर गर्छ।"}'::jsonb,true),
('bmlt-micro-mcq-005','BMLT','Medical Microbiology','mcq','free',5,'{"question":"Which test differentiates Staphylococcus from Streptococcus?","translation":"Staphylococcus र Streptococcus छुट्याउने परीक्षण कुन हो?","options":["Catalase test","Oxidase test","Indole test","Urease test"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"Staphylococci are catalase-positive; streptococci are catalase-negative.","topic":"Staphylococcus catalase positive र Streptococcus catalase negative हुन्छ।"}'::jsonb,true),
('bmlt-micro-mcq-006','BMLT','Medical Microbiology','mcq','free',6,'{"question":"The best routine specimen for diagnosing enteric fever in the first week is:","translation":"Enteric fever को पहिलो हप्तामा उपयुक्त routine specimen कुन हो?","options":["Blood for culture","Urine only","Stool only","Throat swab"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"Blood culture has the highest yield early in enteric fever.","topic":"Enteric fever को पहिलो हप्तामा blood culture बढी उपयोगी हुन्छ।"}'::jsonb,true),
('bmlt-micro-mcq-007','BMLT','Medical Microbiology','mcq','free',7,'{"question":"A characteristic feature of Clostridium tetani is:","translation":"Clostridium tetani को विशेषता कुन हो?","options":["Terminal drumstick-shaped spore","Acid-fast bacillus","Kidney-shaped diplococci","Budding yeast"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"C. tetani forms terminal spores giving a drumstick appearance.","topic":"C. tetani को terminal spore ले drumstick जस्तो आकार दिन्छ।"}'::jsonb,true),
('bmlt-micro-mcq-008','BMLT','Medical Microbiology','mcq','free',8,'{"question":"Which bacterium is classically associated with pseudomembranous colitis after antibiotics?","translation":"Antibiotic पछि pseudomembranous colitis सँग सम्बन्धित जीवाणु कुन हो?","options":["Clostridioides difficile","Vibrio cholerae","Shigella dysenteriae","Bordetella pertussis"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"C. difficile toxins can cause antibiotic-associated colitis.","topic":"C. difficile का toxins ले antibiotic-associated colitis गराउन सक्छन्।"}'::jsonb,true),
('bmlt-micro-mcq-009','BMLT','Medical Microbiology','mcq','free',9,'{"question":"The oxidase test is typically positive in:","translation":"Oxidase test सामान्यतया कुनमा positive हुन्छ?","options":["Pseudomonas aeruginosa","Escherichia coli","Klebsiella pneumoniae","Shigella species"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"P. aeruginosa is oxidase-positive, helping distinguish it from many Enterobacterales.","topic":"P. aeruginosa oxidase positive हुन्छ; धेरै Enterobacterales negative हुन्छन्।"}'::jsonb,true),
('bmlt-micro-mcq-010','BMLT','Medical Microbiology','mcq','free',10,'{"question":"A common screening test for syphilis is:","translation":"Syphilis screening का लागि सामान्य test कुन हो?","options":["VDRL or RPR","Widal test","Mantoux test","Weil-Felix test"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"VDRL and RPR are non-treponemal screening tests; confirmation uses treponemal tests.","topic":"VDRL/RPR screening हुन्; पुष्टि गर्न treponemal test चाहिन्छ।"}'::jsonb,true),
('bmlt-micro-mcq-011','BMLT','Medical Microbiology','mcq','free',11,'{"question":"Hepatitis B surface antigen (HBsAg) indicates:","translation":"HBsAg positive हुनुको अर्थ के हो?","options":["Current HBV infection may be present","Immunity from vaccination only","Past infection with no possibility of current infection","Hepatitis A infection"],"correctIndex":0,"explanation":"Virology","explanationNe":"HBsAg indicates current HBV infection; interpretation needs the full serologic profile.","topic":"HBsAg ले वर्तमान HBV infection संकेत गर्न सक्छ; अन्य markers पनि हेर्नुपर्छ।"}'::jsonb,true),
('bmlt-micro-mcq-012','BMLT','Medical Microbiology','mcq','free',12,'{"question":"The preferred specimen for molecular diagnosis of many respiratory viral infections is:","translation":"धेरै respiratory viral infection को molecular diagnosis का लागि उपयुक्त नमुना कुन हो?","options":["Nasopharyngeal swab/aspirate","Hair sample","Stool in all cases","Bone marrow"],"correctIndex":0,"explanation":"Virology","explanationNe":"A properly collected respiratory swab is commonly used for viral NAAT/PCR.","topic":"Respiratory virus PCR का लागि सही तरिकाले लिएको nasopharyngeal swab प्रयोग हुन्छ।"}'::jsonb,true),
('bmlt-micro-mcq-013','BMLT','Medical Microbiology','mcq','free',13,'{"question":"HIV primarily targets cells expressing which receptor?","translation":"HIV ले मुख्यतः कुन receptor भएका cell लाई target गर्छ?","options":["CD4","CD8","CD19","CD56"],"correctIndex":0,"explanation":"Virology","explanationNe":"HIV binds CD4 and a co-receptor such as CCR5 or CXCR4.","topic":"HIV CD4 र CCR5 वा CXCR4 co-receptor मा bind गर्छ।"}'::jsonb,true),
('bmlt-micro-mcq-014','BMLT','Medical Microbiology','mcq','free',14,'{"question":"Which virus is associated with cervical cancer?","translation":"Cervical cancer सँग कुन virus सम्बन्धित छ?","options":["Human papillomavirus (HPV)","Rotavirus","Rabies virus","Norovirus"],"correctIndex":0,"explanation":"Virology","explanationNe":"Persistent infection with high-risk HPV types, especially 16 and 18, is a major cause.","topic":"High-risk HPV, विशेष गरी 16 र 18, cervical cancer को प्रमुख कारण हो।"}'::jsonb,true),
('bmlt-micro-mcq-015','BMLT','Medical Microbiology','mcq','free',15,'{"question":"The infective stage of Entamoeba histolytica for humans is:","translation":"मानिसमा Entamoeba histolytica को infective stage कुन हो?","options":["Mature quadrinucleate cyst","Trophozoite in blood","Egg","Larva"],"correctIndex":0,"explanation":"Parasitology","explanationNe":"Humans acquire infection by ingesting mature cysts in contaminated food or water.","topic":"दूषित खाना वा पानीबाट mature quadrinucleate cyst निल्दा संक्रमण हुन्छ।"}'::jsonb,true),
('bmlt-micro-mcq-016','BMLT','Medical Microbiology','mcq','free',16,'{"question":"Malaria is transmitted by the bite of:","translation":"Malaria कसको टोकाइबाट सर्छ?","options":["Female Anopheles mosquito","Male Anopheles mosquito","Aedes mosquito only","Sandfly"],"correctIndex":0,"explanation":"Parasitology","explanationNe":"Female Anopheles mosquitoes transmit Plasmodium parasites.","topic":"Female Anopheles लामखुट्टेले Plasmodium सार्छ।"}'::jsonb,true),
('bmlt-micro-mcq-017','BMLT','Medical Microbiology','mcq','free',17,'{"question":"The diagnostic stage of Giardia lamblia commonly found in formed stool is:","translation":"Formed stool मा Giardia lamblia को कुन stage भेटिन सक्छ?","options":["Cyst","Adult worm","Egg","Schizont"],"correctIndex":0,"explanation":"Parasitology","explanationNe":"Giardia cysts are commonly found in formed stool; trophozoites may occur in diarrheal stool.","topic":"Formed stool मा Giardia cyst सामान्यतया भेटिन्छ; पातलो दिसामा trophozoite पनि हुन सक्छ।"}'::jsonb,true),
('bmlt-micro-mcq-018','BMLT','Medical Microbiology','mcq','free',18,'{"question":"The Kato–Katz technique is commonly used to quantify:","translation":"Kato–Katz technique मुख्यतः के quantify गर्न प्रयोग हुन्छ?","options":["Helminth eggs in stool","Bacteria in blood","Viruses in serum","Fungi in skin scrapings"],"correctIndex":0,"explanation":"Parasitology","explanationNe":"Kato–Katz thick smear estimates eggs per gram of stool for intestinal helminths.","topic":"Kato–Katz ले दिसामा helminth eggs प्रति gram अनुमान गर्छ।"}'::jsonb,true),
('bmlt-micro-mcq-019','BMLT','Medical Microbiology','mcq','free',19,'{"question":"The fungal stain commonly used for examining dermatophytes in skin scrapings is:","translation":"Skin scraping मा dermatophyte हेर्न कुन preparation सामान्य हो?","options":["KOH mount","Gram stain only","Widal test","Ziehl–Neelsen stain"],"correctIndex":0,"explanation":"Mycology","explanationNe":"KOH clears keratin and helps visualize fungal hyphae.","topic":"KOH ले keratin clear गरी fungal hyphae देख्न मद्दत गर्छ।"}'::jsonb,true),
('bmlt-micro-mcq-020','BMLT','Medical Microbiology','mcq','free',20,'{"question":"Cryptococcus neoformans can be demonstrated in CSF using:","translation":"CSF मा Cryptococcus neoformans देखाउन कुन test प्रयोग गर्न सकिन्छ?","options":["Cryptococcal antigen test","Coagulase test","Oxidase test","ASO titre"],"correctIndex":0,"explanation":"Mycology","explanationNe":"Cryptococcal antigen testing in CSF is highly useful for diagnosis.","topic":"CSF मा cryptococcal antigen test निदानका लागि उपयोगी हुन्छ।"}'::jsonb,true),
('bmlt-micro-mock-001','BMLT','Medical Microbiology','mock','free',1,'{"question":"A blood culture from a patient with suspected sepsis grows a Gram-negative bacillus that is lactose-fermenting on MacConkey agar. A likely organism is:","translation":"Sepsis को blood culture मा Gram-negative bacillus र MacConkey मा lactose fermenter देखियो। सम्भावित जीव कुन हो?","options":["Escherichia coli","Salmonella Typhi","Shigella flexneri","Pseudomonas aeruginosa"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"E. coli commonly ferments lactose, producing pink colonies on MacConkey agar.","topic":"E. coli lactose fermenter हो र MacConkey मा pink colony बनाउँछ।"}'::jsonb,true),
('bmlt-micro-mock-002','BMLT','Medical Microbiology','mock','free',2,'{"question":"A patient has urethral discharge; intracellular Gram-negative diplococci are seen in a smear. The likely pathogen is:","translation":"Urethral discharge मा intracellular Gram-negative diplococci देखिए कुन pathogen सम्भावित हो?","options":["Neisseria gonorrhoeae","Moraxella catarrhalis","Staphylococcus aureus","Haemophilus influenzae"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"Intracellular Gram-negative diplococci in a symptomatic male urethral specimen suggest N. gonorrhoeae.","topic":"लक्षण भएको पुरुषको urethral smear मा intracellular Gram-negative diplococci N. gonorrhoeae को संकेत हो।"}'::jsonb,true),
('bmlt-micro-mock-003','BMLT','Medical Microbiology','mock','free',3,'{"question":"A stool sample shows curved comma-shaped bacteria and the patient has profuse watery diarrhea. The likely organism is:","translation":"दिसामा comma-shaped bacteria र धेरै पातलो पानीजस्तो पखाला छ। सम्भावित जीव कुन हो?","options":["Vibrio cholerae","Campylobacter jejuni","Yersinia enterocolitica","Proteus mirabilis"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"V. cholerae is a curved, comma-shaped bacillus associated with profuse watery diarrhea.","topic":"V. cholerae comma-shaped जीवाणु हो र profuse watery diarrhea गराउँछ।"}'::jsonb,true),
('bmlt-micro-mock-004','BMLT','Medical Microbiology','mock','free',4,'{"question":"A positive CAMP test supports identification of:","translation":"CAMP test positive हुँदा कुन जीवाणुको पहिचानमा मद्दत हुन्छ?","options":["Streptococcus agalactiae","Streptococcus pyogenes","Staphylococcus epidermidis","Enterococcus faecium"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"Group B Streptococcus (S. agalactiae) is classically CAMP-positive.","topic":"Group B Streptococcus अर्थात् S. agalactiae CAMP positive हुन्छ।"}'::jsonb,true),
('bmlt-micro-mock-005','BMLT','Medical Microbiology','mock','free',5,'{"question":"A bacterial isolate is bile-esculin positive and grows in 6.5% NaCl. It is most consistent with:","translation":"Bile-esculin positive र 6.5% NaCl मा बढ्ने isolate कुन हो?","options":["Enterococcus species","Streptococcus pneumoniae","Streptococcus pyogenes","Neisseria meningitidis"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"Enterococci commonly hydrolyze esculin in bile and tolerate 6.5% NaCl.","topic":"Enterococcus bile-esculin positive र 6.5% NaCl सहन सक्छ।"}'::jsonb,true),
('bmlt-micro-mock-006','BMLT','Medical Microbiology','mock','free',6,'{"question":"A child with a barking cough and inspiratory whoop is suspected of pertussis. The causative organism is:","translation":"Barking cough र inspiratory whoop भएको बच्चामा pertussis शंका छ। कारण जीव कुन हो?","options":["Bordetella pertussis","Corynebacterium diphtheriae","Mycoplasma pneumoniae","Legionella pneumophila"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"B. pertussis causes whooping cough; nasopharyngeal sampling is preferred.","topic":"B. pertussis ले whooping cough गराउँछ; nasopharyngeal sample उपयुक्त हुन्छ।"}'::jsonb,true),
('bmlt-micro-mock-007','BMLT','Medical Microbiology','mock','free',7,'{"question":"A laboratory needs to distinguish Candida albicans from many other Candida species rapidly. A classic test is:","translation":"Candida albicans लाई अन्य Candida बाट छिटो छुट्याउने classic test कुन हो?","options":["Germ tube test","Indole test","CAMP test","Bile solubility test"],"correctIndex":0,"explanation":"Mycology","explanationNe":"C. albicans typically forms germ tubes in serum under suitable conditions.","topic":"C. albicans उपयुक्त serum condition मा germ tube बनाउँछ।"}'::jsonb,true),
('bmlt-micro-mock-008','BMLT','Medical Microbiology','mock','free',8,'{"question":"A patient with suspected invasive aspergillosis has septate hyphae with acute-angle branching. The likely fungus is:","translation":"Invasive aspergillosis शंका हुँदा septate hyphae र acute-angle branching देखियो। कुन fungus?","options":["Aspergillus species","Mucor species","Candida glabrata","Cryptococcus only"],"correctIndex":0,"explanation":"Mycology","explanationNe":"Aspergillus typically shows septate hyphae with acute-angle branching.","topic":"Aspergillus मा septate hyphae र acute-angle branching देखिन्छ।"}'::jsonb,true),
('bmlt-micro-mock-009','BMLT','Medical Microbiology','mock','free',9,'{"question":"A thick blood film is preferred in malaria microscopy because it:","translation":"Malaria microscopy मा thick blood film किन प्राथमिक हुन्छ?","options":["Concentrates parasites for detection","Preserves RBC morphology best","Identifies species by RBC size alone","Is always parasite-free after staining"],"correctIndex":0,"explanation":"Parasitology","explanationNe":"Thick films examine a larger blood volume and improve parasite detection sensitivity.","topic":"Thick film ले बढी blood volume हेर्ने भएकाले parasite पत्ता लगाउने sensitivity बढ्छ।"}'::jsonb,true),
('bmlt-micro-mock-010','BMLT','Medical Microbiology','mock','free',10,'{"question":"A thin blood film in malaria is especially useful for:","translation":"Malaria मा thin blood film विशेष गरी केका लागि उपयोगी हुन्छ?","options":["Species identification and parasite morphology","Screening all bacteria","Counting stool ova","Detecting fungal spores"],"correctIndex":0,"explanation":"Parasitology","explanationNe":"Thin films preserve RBC and parasite morphology, helping species identification.","topic":"Thin film ले RBC र parasite morphology जोगाउँछ, species छुट्याउन मद्दत गर्छ।"}'::jsonb,true),
('bmlt-micro-mock-011','BMLT','Medical Microbiology','mock','free',11,'{"question":"A stool specimen contains barrel-shaped eggs with bipolar plugs. The parasite is:","translation":"दिसामा bipolar plugs भएका barrel-shaped eggs भेटिए कुन parasite हो?","options":["Trichuris trichiura","Ascaris lumbricoides","Ancylostoma duodenale","Taenia saginata"],"correctIndex":0,"explanation":"Parasitology","explanationNe":"Trichuris eggs are barrel-shaped with characteristic bipolar plugs.","topic":"Trichuris को अण्डा barrel-shaped र दुवै छेउमा bipolar plug हुन्छ।"}'::jsonb,true),
('bmlt-micro-mock-012','BMLT','Medical Microbiology','mock','free',12,'{"question":"A perianal cellophane tape test is used to diagnose:","translation":"Perianal cellophane tape test कुन रोग निदान गर्न प्रयोग हुन्छ?","options":["Enterobius vermicularis infection","Giardiasis","Amoebiasis","Schistosomiasis"],"correctIndex":0,"explanation":"Parasitology","explanationNe":"Female pinworms deposit eggs around the anus, especially at night.","topic":"Pinworm ले राति anus वरिपरि अण्डा राख्छ; tape test उपयोगी हुन्छ।"}'::jsonb,true),
('bmlt-micro-mock-013','BMLT','Medical Microbiology','mock','free',13,'{"question":"An encapsulated yeast with a positive India ink preparation in CSF suggests:","translation":"CSF मा India ink positive encapsulated yeast देखिए के शंका हुन्छ?","options":["Cryptococcus neoformans","Candida tropicalis","Aspergillus fumigatus","Trichophyton rubrum"],"correctIndex":0,"explanation":"Mycology","explanationNe":"Cryptococcus has a prominent capsule that may be demonstrated by India ink.","topic":"Cryptococcus को capsule India ink मा देखिन सक्छ।"}'::jsonb,true),
('bmlt-micro-mock-014','BMLT','Medical Microbiology','mock','free',14,'{"question":"A suspected dermatophyte infection is cultured on a medium containing antibiotics and cycloheximide. The medium is:","translation":"Dermatophyte culture का लागि antibiotic र cycloheximide भएको medium कुन हो?","options":["Mycosel agar","MacConkey agar","Blood agar","CLED agar"],"correctIndex":0,"explanation":"Mycology","explanationNe":"Mycosel agar suppresses many bacteria and contaminating fungi while supporting dermatophytes.","topic":"Mycosel agar ले bacteria र contaminating fungi रोक्दै dermatophyte बढ्न मद्दत गर्छ।"}'::jsonb,true),
('bmlt-micro-mock-015','BMLT','Medical Microbiology','mock','free',15,'{"question":"A patient develops fever after a transfusion and the blood bag is suspected of bacterial contamination. The immediate laboratory action is to:","translation":"Transfusion पछि fever आयो र blood bag bacterial contamination शंका भयो। तत्काल lab action?","options":["Notify blood bank/clinical team and culture patient and component per protocol","Discard all records and do not investigate","Issue another unit without checking","Only repeat hemoglobin"],"correctIndex":0,"explanation":"Bacteriology","explanationNe":"Suspected transfusion-associated sepsis requires prompt notification and appropriate cultures/investigation.","topic":"Transfusion-associated sepsis शंका हुँदा तुरुन्त blood bank/clinical team लाई खबर गरी protocol अनुसार culture गर्नुपर्छ।"}'::jsonb,true),
('bmlt-micro-mock-016','BMLT','Medical Microbiology','mock','free',16,'{"question":"A rapid test detects antibodies to HIV. A reactive screening result should be followed by:","translation":"HIV antibody screening reactive आयो। त्यसपछि के गर्नुपर्छ?","options":["The national/validated confirmatory testing algorithm","Immediate final diagnosis without confirmation","Widal test","Only repeat urine microscopy"],"correctIndex":0,"explanation":"Virology","explanationNe":"HIV diagnosis follows a validated national testing algorithm; screening alone is not definitive.","topic":"HIV diagnosis validated national algorithm अनुसार पुष्टि गर्नुपर्छ; screening मात्र अन्तिम diagnosis होइन।"}'::jsonb,true),
('bmlt-micro-mock-017','BMLT','Medical Microbiology','mock','free',17,'{"question":"Which hepatitis B marker is most associated with active viral replication and high infectivity?","translation":"HBV मा active viral replication र high infectivity सँग कुन marker बढी सम्बन्धित छ?","options":["HBeAg","Anti-HBs alone","Anti-HBc IgG alone","Anti-HAV IgM"],"correctIndex":0,"explanation":"Virology","explanationNe":"HBeAg often correlates with active replication and higher infectivity, though HBV DNA is the direct measure.","topic":"HBeAg active replication र infectivity सँग सम्बन्धित हुन्छ; HBV DNA प्रत्यक्ष मापन हो।"}'::jsonb,true),
('bmlt-micro-mock-018','BMLT','Medical Microbiology','mock','free',18,'{"question":"A laboratory uses a negative control in an ELISA run primarily to:","translation":"ELISA मा negative control किन राखिन्छ?","options":["Detect nonspecific/background signal and verify assay performance","Increase patient antibody concentration","Replace the calibrator in every assay","Determine blood group"],"correctIndex":0,"explanation":"Immunology","explanationNe":"A negative control helps assess background reactivity and run validity.","topic":"Negative control ले background reactivity र assay validity जाँच्न मद्दत गर्छ।"}'::jsonb,true),
('bmlt-micro-mock-019','BMLT','Medical Microbiology','mock','free',19,'{"question":"The antigen-antibody reaction used in latex agglutination is visually detected by:","translation":"Latex agglutination मा antigen-antibody reaction कसरी देखिन्छ?","options":["Visible clumping of particles","Colorless sediment only in every test","Gas formation","Hemolysis of all RBCs"],"correctIndex":0,"explanation":"Immunology","explanationNe":"Specific antigen-antibody binding cross-links latex particles, producing visible agglutination.","topic":"Antigen-antibody binding ले latex particles जोडेर visible clumping बनाउँछ।"}'::jsonb,true),
('bmlt-micro-mock-020','BMLT','Medical Microbiology','mock','free',20,'{"question":"A laboratory worker has a needlestick exposure to potentially infectious blood. The first appropriate step is:","translation":"संक्रमित हुन सक्ने रगतको needlestick exposure भयो। पहिलो उचित कदम कुन हो?","options":["Wash the site with soap and water and report immediately","Squeeze aggressively and apply bleach","Ignore if the needle looked clean","Wait several days before reporting"],"correctIndex":0,"explanation":"Biosafety","explanationNe":"Immediate washing and prompt reporting allow timely risk assessment and post-exposure management.","topic":"घाउ साबुनपानीले धुने र तुरुन्त report गर्ने; त्यसपछि exposure assessment र PEP निर्णय हुन्छ।"}'::jsonb,true)
